    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(('NUM', int(expr[i:j])))
            i = j
        elif c in '+-*/()':
            tokens.append((c, c))
            i += 1
        else:
            raise ValueError(f"Unexpected character: {c}")

    pos = 0

    def peek():
        if pos < len(tokens):
            return tokens[pos]
        return (None, None)

    def idiv(a, b):
        q = abs(a) // abs(b)
        if (a < 0) != (b < 0):
            q = -q
        return q

    def parse_expr():
        nonlocal pos
        val = parse_term()
        while True:
            tok_type, tok_val = peek()
            if tok_type == '+':
                pos += 1
                val = val + parse_term()
            elif tok_type == '-':
                pos += 1
                val = val - parse_term()
            else:
                break
        return val

    def parse_term():
        nonlocal pos
        val = parse_factor()
        while True:
            tok_type, tok_val = peek()
            if tok_type == '*':
                pos += 1
                val = val * parse_factor()
            elif tok_type == '/':
                pos += 1
                val = idiv(val, parse_factor())
            else:
                break
        return val

    def parse_factor():
        nonlocal pos
        tok_type, tok_val = peek()
        if tok_type == '-':
            pos += 1
            return -parse_factor()
        return parse_primary()

    def parse_primary():
        nonlocal pos
        tok_type, tok_val = peek()
        if tok_type == 'NUM':
            pos += 1
            return tok_val
        elif tok_type == '(':
            pos += 1
            val = parse_expr()
            tok_type2, tok_val2 = peek()
            if tok_type2 != ')':
                raise ValueError("Expected ')'")
            pos += 1
            return val
        else:
            raise ValueError(f"Unexpected token: {tok_type}")

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError("Unexpected trailing tokens")
    return result

